/*
 * spu_run(2) minimal demonstration using syscall(2).
 * Note: This code assumes required setup (like spu_create(2) and loading SPU code)
 * has occurred and relevant headers and system constants are available.
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/syscall.h>
#include <errno.h>

/* Define constants if system headers are incomplete (SYS_spu_run differs by arch) */
#ifndef SYS_spu_run
/* Placeholder for the real system call number, which varies by architecture */
#define SYS_spu_run 345 
#endif

int main() {
    /* Assume 'spu_fd' is a valid file descriptor for a created SPU context */
    /* In a real scenario, this FD would be returned by spu_create(2) */
    int spu_fd = 5; 
    uint32_t start_pc = 0x1000; /* Entry point for SPU code */
    uint32_t final_pc = start_pc;
    uint32_t event_status = 0;
    long ret;

    printf("Attempting to run SPU context %d starting at PC 0x%X...\n", spu_fd, final_pc);

    /* 
     * Invoke spu_run(fd, npc, event) via syscall(2).
     * This call blocks until the SPU execution completes.
     */
    ret = syscall(SYS_spu_run, 
                  spu_fd, 
                  &final_pc, 
                  &event_status);

    if (ret == -1) {
        /* Handle typical errors like EBADF if the FD is invalid or ENOENT if the syscall is not supported */
        perror("syscall(SYS_spu_run) failed");
        return EXIT_FAILURE;
    }

    printf("SPU execution completed synchronously.\n");
    printf("Final PC value written back: 0x%X\n", final_pc);
    if (event_status != 0) {
        printf("SPU reported events/status: 0x%X\n", event_status);
    }

    /* Cleanup (e.g., close(spu_fd)) follows */

    return EXIT_SUCCESS;
}
